from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wtime = cache[key]
        return t >= wtime + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # purge expired entry if present
            if key in cache and is_expired(key, t):
                del cache[key]

            if key in cache:
                # update existing, move to end
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache and is_expired(key, t):
                del cache[key]

            if key in cache:
                value, wtime = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

